import re
p = 'src/PhpStan/Rule/Architecture/ForbiddenFileTermInspector.php'
s = open(p).read()

old_use = "use function file;\nuse function is_array;\n"
new_use = "use function file;\nuse function is_array;\nuse function is_file;\nuse function is_readable;\n"
assert old_use in s
s = s.replace(old_use, new_use, 1)

old = """        $lines = @file($filePath, FILE_IGNORE_NEW_LINES);
        if (!is_array($lines)) {
            return [];
        }
"""
new = """        if (!is_file($filePath) || !is_readable($filePath)) {
            return [];
        }

        $lines = file($filePath, FILE_IGNORE_NEW_LINES);
        if (!is_array($lines)) {
            return [];
        }
"""
assert old in s
s = s.replace(old, new, 1)
open(p, 'w').write(s)
print("patched")
PY

